# Main processing
# ═══════════════════════════════════════════════════════════════════════════════

def process_case(case: dict,
                 identities: dict,
                 audit_log: list[dict],
                 evidence_store: EvidenceStore,
                 sql_manifest: list[dict],
                 activity_rows: list[dict],
                 deletion_rules: dict) -> dict:
    """Process a single deletion request case."""
    case_id = case["case_id"]
    email = case["email"]
    request_text = case.get("request_text", "")
    audit_at = case["audit_at"]

    # Step 1: Is this a deletion request?
    if not is_deletion_request(request_text):
        return {
            "case_id": case_id,
            "deletion_status": "NOT_APPLICABLE",
            "steps_json": "[]",
        }

    # Step 2: Resolve user identity
    user_id, all_emails, all_phones = resolve_user(email, identities, audit_log)

    # Step 3: Find all relevant evidence records
    evidence_records = evidence_store.find_records_for_user(user_id, all_emails, all_phones, audit_at)

    # Step 4: Also search SQL evidence
    sql_records = search_sql_evidence(sql_manifest, all_emails, all_phones, user_id, audit_at)
    evidence_records.extend(sql_records)

    # Step 5: Determine deletion status
    status = determine_status(evidence_records, deletion_rules)

    # Step 6: Build steps
    is_complete = status == "COMPLETE"
    steps = build_steps(evidence_records, deletion_rules, user_id, is_complete)

    # If COMPLETE but no steps, add at minimum an account verification
    # Using system activity to find the account resource_id
    if is_complete and not steps:
        # Try to find account resource ID from system activity
        account_resource = find_account_resource_for_user(case_id, user_id, all_emails, activity_rows)
        if account_resource:
            sys_id, res_id, ev_id = account_resource
            steps = [make_step(1, "VERIFICATION", sys_id, res_id,
                               "VERIFY_RECORD_ABSENT", "ABSENT", ev_id)]

    steps_json = json.dumps(steps, ensure_ascii=False, separators=(",", ":"))

    return {
        "case_id": case_id,
        "deletion_status": status,
        "steps_json": steps_json,
    }


def find_account_resource_for_user(case_id: str,
                                    user_id: Optional[str],
                                    all_emails: set[str],
                                    activity_rows: list[dict]) -> Optional[tuple]:
    """
    Try to find an account resource_id for a user from system activity.
    Returns (system_id, resource_id, activity_id) or None.
    """
    for row in activity_rows:
        resource_id = row.get("resource_id", "")
        details = row.get("details", "").lower()
        target_system = row.get("target_system", "account_service")
        activity_id = row.get("activity_id", "")

        if "account_" in resource_id.lower():
            matched = False
            for email in all_emails:
                if email and email in details:
                    matched = True
                    break
            if not matched and user_id and user_id in details:
                matched = True
            if matched:
                return (target_system or "account_service", resource_id, activity_id)

    return None


