            emails = [e for e in [ticket.get("requester_email")] if e and "@" in e]
            refs = [ticket.get("customer_reference")]
            rec = {
                "file_id": file_id, "captured_at": captured_at,
                "system": "support_platform", "resource_id": ticket.get("resource_id"),
                "type": "support_ticket", "raw": ticket,
            }
            self._add_to_index(emails, [r for r in refs if r], rec)
        # marketing_platform (sometimes in generic json exports)
        for prof in exports.get("marketing_platform", {}).get("profiles", []):
            emails = [e for e in [prof.get("email")] if e and "@" in e]
            refs = [prof.get("customer_reference")]
            rec = {
                "file_id": file_id, "captured_at": captured_at,
                "system": "marketing_platform", "resource_id": prof.get("resource_id"),
                "type": "marketing_profile", "raw": prof,
            }
            self._add_to_index(emails, [r for r in refs if r], rec)
    def _index_snapshot_bundle(self, file_id: str, captured_at: str, content: dict):
        """Index customer_data_snapshot_bundle.json"""
        for snapshot in content.get("snapshots", []):
            data_store = snapshot.get("data_store", "")
            collection = snapshot.get("collection", "")
            records = snapshot.get("records", [])
            for rec_data in records:
                emails = []
                refs = []
                for field in ["email", "owner_email", "requester_email"]:
                    v = rec_data.get(field)
                    if v and "@" in v:
                        emails.append(v.strip().lower())
                for field in ["subject_reference", "customer_reference", "user_id"]:
                    v = rec_data.get(field)
                    if v:
                        refs.append(v.strip())
                rec_type = "snapshot_record"
                if "tombstone" in collection.lower() or "deleted" in collection.lower():
                    rec_type = "tombstone"
                elif "audit" in collection.lower():
                    rec_type = "audit_record"
                rec = {
                    "file_id": file_id, "captured_at": captured_at,
                    "system": data_store, "resource_id": rec_data.get("resource_id"),
                    "type": rec_type, "collection": collection, "raw": rec_data,
                }
                self._add_to_index(emails, refs, rec)
    def _index_generic_json(self, file_id: str, captured_at: str, content: dict):
        """Try to index any other JSON structure by recursively looking for emails/user_refs."""
        # Flatten JSON to extract any records
        self._index_json_node(file_id, captured_at, content, path="root")
    def _index_json_node(self, file_id: str, captured_at: str, node: Any, path: str, depth: int = 0):
        if depth > 6:
            return
        if isinstance(node, list):
            for i, item in enumerate(node):
                self._index_json_node(file_id, captured_at, item, f"{path}[{i}]", depth + 1)
        elif isinstance(node, dict):
            emails = []
            refs = []
            resource_id = node.get("resource_id") or node.get("id")
            for k, v in node.items():
                if v and isinstance(v, str):
                    vl = v.strip().lower()
                    if k in ("email", "owner_email", "requester_email", "customer_email") and "@" in v:
                        emails.append(vl)
                    elif k in ("user_id", "subject_reference", "customer_reference") and v:
                        refs.append(v.strip())
                    elif k == "resource_id" and v:
                        resource_id = v
            if emails or refs:
                # Determine system from path or node structure
                system = "unknown"
                for sys_name in SYSTEM_CATEGORY_MAP:
                    if sys_name in path.lower():
                        system = sys_name
                        break
                rec = {
                    "file_id": file_id, "captured_at": captured_at,
                    "system": system, "resource_id": resource_id,
                    "type": "generic", "raw": node,
                }
                self._add_to_index(emails, refs, rec)
            # Recurse into children
            for k, v in node.items():
                if isinstance(v, (dict, list)):
                    self._index_json_node(file_id, captured_at, v, f"{path}.{k}", depth + 1)
    def _index_text(self, file_id: str, captured_at: str, content: str, file_path: str):
        """Index log files by parsing structured log lines."""
        lines = content.split("\n")
        for line in lines:
            if "event=profile_lookup_completed" in line or "event=index_query_completed" in line \
                    or "event=analytics_profile_read_completed" in line \
                    or "event=connector_config_read_completed" in line \
                    or "event=restore_policy_read_completed" in line \
                    or "event=support_ticket_read_completed" in line \
                    or "event=audit_record_read_completed" in line:
                # Extract fields from key=value structured log
                fields = {}
                for match in re.finditer(r'(\w+)=([^\s]+)', line):
                    fields[match.group(1)] = match.group(2)
                emails = []
                refs = []
                for k in ("lookup_key", "customer_email", "requester_email"):
                    v = fields.get(k, "null")
                    if v and v != "null" and "@" in v:
                        emails.append(v.strip().lower())
                for k in ("customer_reference",):
                    v = fields.get(k, "null")
                    if v and v != "null" and v.startswith("user_"):
                        refs.append(v.strip())
                resource_id = fields.get("resource_id", "")
                service = fields.get("service", "unknown")
                # Map service name to system id
                system = service
                # Determine type and state from the log line
                rec_type = "log_record"
                extra = {}
                if "enabled" in fields:
                    extra["enabled"] = fields["enabled"] == "true"
                if "restore_allowed" in fields:
                    extra["restore_allowed"] = fields.get("restore_allowed") == "true"
                if "http_status" in fields:
                    extra["status_code"] = int(fields.get("http_status", 0))
                if "rows" in fields:
                    extra["rows"] = int(fields.get("rows", 0))
                if "result" in fields:
                    extra["result"] = fields.get("result")
                if "retention_until" in fields:
                    extra["retention_until"] = fields.get("retention_until")
                if "event_code" in fields:
                    extra["event_code"] = fields.get("event_code")
                rec = {
                    "file_id": file_id, "captured_at": captured_at,
                    "system": system, "resource_id": resource_id,
                    "type": rec_type, "raw": fields, **extra,
                }
                self._add_to_index(emails, refs, rec)
    def find_records_for_user(self,
                               user_id: Optional[str],
                               all_emails: set[str],
                               all_phones: set[str],
                               audit_at: str) -> list[dict]:
        """
        Return all evidence records for this user captured at or before audit_at.
        """
        self.build_index()
        audit_ts = parse_iso(audit_at)
        seen = set()  # (file_id, system, resource_id)
        results = []
        def add_if_new(rec: dict):
            key = (rec["file_id"], rec["system"], rec["resource_id"])
            if key not in seen:
                # Check captured_at
                cap_ts = parse_iso(rec.get("captured_at", ""))
                if cap_ts and cap_ts <= audit_ts:
                    seen.add(key)
                    results.append(rec)
        # Search by email
        for email in all_emails:
            for rec in self._email_index.get(email, []):
                add_if_new(rec)
        # Search by user_id reference
        if user_id:
            for rec in self._user_ref_index.get(user_id, []):
                add_if_new(rec)
        return results
def parse_iso(ts: str) -> Optional[datetime]:
    if not ts:
        return None
    try:
        ts = ts.strip().rstrip("Z")
        if "." in ts:
            ts = ts.split(".")[0]
        return datetime.fromisoformat(ts).replace(tzinfo=timezone.utc)
    except Exception:
        return None
# ═══════════════════════════════════════════════════════════════════════════════
# SQL evidence parsing
# ═══════════════════════════════════════════════════════════════════════════════
def search_sql_evidence(manifest: list[dict],
                         all_emails: set[str],
                         all_phones: set[str],
                         user_id: Optional[str],
                         audit_at: str) -> list[dict]:
    """Search SQL evidence files for user records."""
    audit_ts = parse_iso(audit_at)
    results = []
    for entry in manifest:
        file_id = entry["file_id"]
        file_path = entry["file_path"]
        captured_at = entry["captured_at"]
        cap_ts = parse_iso(captured_at)
        if cap_ts and audit_ts and cap_ts > audit_ts:
            continue  # Skip files captured after audit_at
        if not file_path.endswith(".sql"):
            continue
        full_path = DATASET / file_path
        if not full_path.exists():
            continue
        try:
            with open(full_path, encoding="utf-8") as f:
                sql_content = f.read()
        except Exception:
            continue
        # Load SQL into in-memory SQLite
        try:
            conn = sqlite3.connect(":memory:")
            conn.row_factory = sqlite3.Row
            cursor = conn.cursor()
            # Execute the SQL dump
            cursor.executescript(sql_content)
            conn.commit()
            # Get list of tables
            cursor.execute("SELECT name FROM sqlite_master WHERE type='table'")
            tables = [row[0] for row in cursor.fetchall()]
            for table in tables:
                try:
                    cursor.execute(f'PRAGMA table_info("{table}")')
                    columns = [col[1] for col in cursor.fetchall()]
                    # Build WHERE clause for email/phone/user_id match
                    conditions = []
                    params = []
                    for col in columns:
                        col_lower = col.lower()
                        if col_lower in ("email", "owner_email", "customer_email", "requester_email"):
                            for em in all_emails:
                                conditions.append(f'lower("{col}") = ?')
                                params.append(em.lower())
                        elif col_lower in ("phone", "customer_phone"):
                            for ph in all_phones:
                                conditions.append(f'"{col}" = ?')
                                params.append(ph)
                        elif col_lower in ("user_id", "customer_reference", "subject_reference"):
                            if user_id:
                                conditions.append(f'"{col}" = ?')
                                params.append(user_id)
                    if not conditions:
                        continue
                    where_clause = " OR ".join(conditions)
                    cursor.execute(f'SELECT * FROM "{table}" WHERE {where_clause}', params)
                    rows = cursor.fetchall()
                    for row in rows:
                        row_dict = dict(row)
                        resource_id = (row_dict.get("resource_id") or row_dict.get("id") or
                                       row_dict.get("record_id") or f"{table}_row")
                        # Determine system from table name
                        system = infer_system_from_table(table)
                        rec = {
                            "file_id": file_id, "captured_at": captured_at,
                            "system": system, "resource_id": str(resource_id),
                            "type": "sql_record", "table": table,
                            "raw": row_dict,
                        }
                        results.append(rec)
                except sqlite3.Error:
                    continue
            conn.close()
        except sqlite3.Error:
            continue
    return results
def infer_system_from_table(table_name: str) -> str:
    t = table_name.lower()
    if "account" in t:
        return "account_service"
    if "search" in t or "index" in t:
        return "search_service"
    if "support" in t or "ticket" in t:
        return "support_platform"
    if "analytic" in t:
        return "analytics_platform"
    if "marketing" in t:
        return "marketing_platform"
    if "export" in t:
        return "export_service"
    if "backup" in t or "archive" in t:
        return "backup_service"
    if "audit" in t or "security" in t:
        return "security_service"
    if "integration" in t or "connector" in t or "data_flow" in t:
        return "integration_service"
    if "tombstone" in t or "deleted" in t or "identity" in t:
        return "identity_service"
    if "email" in t or "delivery" in t or "notification" in t:
        return "email_delivery_service"
    return "unknown"
# ═══════════════════════════════════════════════════════════════════════════════
# System activity search
# ═══════════════════════════════════════════════════════════════════════════════
def search_system_activity(activity_rows: list[dict],
                            user_id: Optional[str],
                            all_emails: set[str],
                            all_phones: set[str],
                            audit_at: str) -> list[dict]:
    """
    Search system_activity.csv for events related to this user.
    Returns activities relevant to deletion (SYNC, RESTORE, EXPORT, BACKUP, etc.)
    """
    audit_ts = parse_iso(audit_at)
    results = []
    for row in activity_rows:
        event_time = row.get("event_time", "")
        ev_ts = parse_iso(event_time)
        if ev_ts and audit_ts and ev_ts > audit_ts:
            continue  # Skip events after audit_at
        details = row.get("details", "").lower()
        resource_id = row.get("resource_id", "")
        matched = False
        for email in all_emails:
            if email and email in details:
                matched = True
                break
        if not matched and user_id:
            if user_id in details:
                matched = True
        if matched:
            results.append(row)
    return results
# ═══════════════════════════════════════════════════════════════════════════════
# Record analysis and classification
# ═══════════════════════════════════════════════════════════════════════════════
def classify_record(rec: dict, deletion_rules: dict) -> tuple[str, str, str]:
    """
    Returns (required_action, data_category, system_id)
    based on the record's system and type.
    """
    system = rec.get("system", "unknown")
    rec_type = rec.get("type", "")
    # Special cases
    if rec_type in ("tombstone", "snapshot_record") and rec.get("collection"):
        col = rec.get("collection", "").lower()
        if "tombstone" in col or "deleted_customer" in col:
            system = "identity_service"
    if rec_type == "data_flow":
        data_cat = "SECONDARY_IDENTIFIER"
        action = deletion_rules.get(data_cat, "DELETE")
        return action, data_cat, "integration_service"
    if rec_type == "backup_restore":
        data_cat = "BACKUP_ARCHIVE"
        action = deletion_rules.get(data_cat, "RETAIN")
        return action, data_cat, "backup_service"
    if rec_type == "audit_record":
        data_cat = "SECURITY_AUDIT_LOG"
        action = deletion_rules.get(data_cat, "RETAIN")
        return action, data_cat, "security_service"
    # Map system to category
    data_cat = SYSTEM_CATEGORY_MAP.get(system, "USER_PROFILE")
    action = deletion_rules.get(data_cat, "DELETE")
    return action, data_cat, system
def is_record_present(rec: dict) -> bool:
    """Determine if this record actually has data (is 'present')."""
    # account_service lookups
    if rec.get("type") == "account_profile":
        return rec.get("status_code") == 200 and rec.get("profile") is not None
    # search index
    if rec.get("type") == "search_index":
        return rec.get("total_hits", 0) > 0
    # analytics_profile - check if has PII
    if rec.get("type") == "analytics_profile":
        profile = rec.get("profile") or rec.get("raw") or {}
        return profile.get("email") is not None or profile.get("customer_reference") is not None
    # data_flow - check enabled
    if rec.get("type") == "data_flow":
        return rec.get("enabled", False)
    # backup - check restore_allowed
    if rec.get("type") == "backup_restore":
        return rec.get("restore_allowed", False)
    # audit_record - always retained
    if rec.get("type") == "audit_record":
        return True  # Must be retained
    # tombstone - check for exposed PII
    if rec.get("type") == "tombstone":
        raw = rec.get("raw", {})
        return any(raw.get(f) is not None for f in ["name", "email", "phone", "email_hash"])
    # log_record
    if rec.get("type") == "log_record":
        status = rec.get("status_code", 200)
        rows = rec.get("rows", 1)
        result = rec.get("result", "hit")
        if status == 404 or rows == 0:
            return False
        return result == "hit" or rows > 0
    # sql_record
    if rec.get("type") == "sql_record":
        return True  # If found in SQL, it's present
    # snapshot_record
    if rec.get("type") == "snapshot_record":
        raw = rec.get("raw", {})
        # For tombstones
        if rec.get("collection") and ("tombstone" in rec.get("collection", "").lower() or
                                       "deleted" in rec.get("collection", "").lower()):
            return any(raw.get(f) is not None for f in ["name", "email", "phone", "email_hash"])
        return True
    return True
def has_pii_exposed(rec: dict) -> bool:
    """Check if a record has PII that should be redacted/anonymized."""
    raw = rec.get("raw") or {}
    profile = rec.get("profile") or {}
    # For analytics profiles - check if email or customer_reference present
    if rec.get("type") == "analytics_profile":
        return (raw.get("email") is not None or
                profile.get("email") is not None or
                raw.get("customer_reference") is not None)
    # For support tickets - check if has identifiable fields
    if rec.get("type") == "support_ticket":
        return (raw.get("requester_email") is not None or
                raw.get("requester_name") is not None or
                raw.get("requester_phone") is not None)
    # For tombstones - check if has exposed PII (name, email, phone, email_hash)
    if rec.get("type") == "tombstone":
        return any(raw.get(f) is not None for f in ["name", "email", "phone", "email_hash"])
    # log records
    if rec.get("type") == "log_record":
        fields = rec.get("raw", {})
        return fields.get("customer_email", "null") not in ("null", "", None)
    return False
# ═══════════════════════════════════════════════════════════════════════════════
# Step generation
# ═══════════════════════════════════════════════════════════════════════════════
def make_step(step_no: int, phase: str, system_id: str, resource_id: str,
              operation: str, state: str, evidence_id: str) -> dict:
    return {
        "step_no": step_no,
        "phase": phase,
        "system_id": system_id,
        "resource_id": resource_id,
        "operation": operation,
        "state": state,
        "evidence_id": evidence_id,
    }
def sort_key_for_step(step: dict, phase_ops_order: dict) -> tuple:
    op = step["operation"]
    op_idx = phase_ops_order.get(step["phase"], {}).get(op, 99)
    return (op_idx, step["system_id"], step["resource_id"])
def build_steps(records: list[dict],
                deletion_rules: dict,
                user_id: Optional[str],
                is_complete: bool) -> list[dict]:
    """
    Build the ordered list of steps (FINDING, REMEDIATION, VERIFICATION).
    For COMPLETE: only verification steps (evidence backed).
    For INCOMPLETE: findings + remediation + verification.
    """
    findings = []
    remediations = []
    verifications = []
    # Track what we've already handled to avoid duplicates
    handled = set()
    for rec in records:
        action, data_cat, system_id = classify_record(rec, deletion_rules)
        resource_id = rec.get("resource_id", "")
        file_id = rec.get("file_id", "")
        if not resource_id:
            continue
        key = (system_id, resource_id)
        if key in handled:
            continue
        handled.add(key)
        present = is_record_present(rec)
        pii_exposed = has_pii_exposed(rec)
        rec_type = rec.get("type", "")
        # ── Data flows ─────────────────────────────────────────────────────────
        if rec_type == "data_flow":
            enabled = rec.get("enabled", False)
            if enabled:
                if not is_complete:
                    findings.append(make_step(0, "FINDING", system_id, resource_id,
                                              "REPORT_ACTIVE_DATA_FLOW", "ACTIVE", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id,
                                                  "DISABLE_DATA_FLOW", "DISABLED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_DATA_FLOW_DISABLED", "DISABLED", ""))
            else:
                # Already disabled - COMPLETE verification
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_DATA_FLOW_DISABLED", "DISABLED", file_id))
            continue
        # ── Backup/restore risk ───────────────────────────────────────────────
        if rec_type == "backup_restore":
            restore_allowed = rec.get("restore_allowed", False)
            if restore_allowed:
                if not is_complete:
                    findings.append(make_step(0, "FINDING", system_id, resource_id,
                                              "REPORT_RESTORE_RISK", "ACTIVE", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id,
                                                  "BLOCK_RESTORE", "BLOCKED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_RESTORE_BLOCKED", "BLOCKED", ""))
            else:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_RESTORE_BLOCKED", "BLOCKED", file_id))
            continue
        # ── Security audit records (always RETAIN) ────────────────────────────
        if rec_type == "audit_record" or data_cat == "SECURITY_AUDIT_LOG":
            # Must be retained - add verification only
            if is_complete:
                verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                               "VERIFY_RECORD_PRESENT", "PRESENT", file_id))
            else:
                verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                               "VERIFY_RECORD_PRESENT", "PRESENT", ""))
            continue
        # ── Account tombstones (REDACT - keep user_id, remove PII) ───────────
        if rec_type == "tombstone" or (data_cat == "ACCOUNT_TOMBSTONE" and system_id == "identity_service"):
            if pii_exposed:
                if not is_complete:
                    findings.append(make_step(0, "FINDING", system_id, resource_id,
                                              "REPORT_EXPOSED_PII", "PRESENT", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id,
                                                  "REDACT_RECORD", "REDACTED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_RECORD_REDACTED", "REDACTED", ""))
            else:
                # Already redacted
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_RECORD_REDACTED", "REDACTED", file_id))
            continue
        # ── Handle records by required action ─────────────────────────────────
        if action == "DELETE":
            if present:
                if not is_complete:
                    findings.append(make_step(0, "FINDING", system_id, resource_id,
                                              "REPORT_REMAINING_RECORD", "PRESENT", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id,
                                                  "DELETE_RECORD", "ABSENT", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_RECORD_ABSENT", "ABSENT", ""))
            else:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_RECORD_ABSENT", "ABSENT", file_id))
        elif action == "REDACT":
            if pii_exposed or present:
                if not is_complete:
                    op = "REPORT_EXPOSED_PII" if pii_exposed else "REPORT_REMAINING_RECORD"
                    findings.append(make_step(0, "FINDING", system_id, resource_id,
                                              op, "PRESENT", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id,
                                                  "REDACT_RECORD", "REDACTED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_RECORD_REDACTED", "REDACTED", ""))
            else:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_RECORD_REDACTED", "REDACTED", file_id))
        elif action == "ANONYMIZE":
            if pii_exposed or present:
                if not is_complete:
                    op = "REPORT_EXPOSED_PII" if pii_exposed else "REPORT_REMAINING_RECORD"
                    findings.append(make_step(0, "FINDING", system_id, resource_id,
                                              op, "PRESENT", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id,
                                                  "ANONYMIZE_RECORD", "ANONYMIZED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id,
                                                   "VERIFY_RECORD_ANONYMIZED", "ANONYMIZED", ""))
            else:
                if is_complete:
