    # ── Deduplicate and sort ──────────────────────────────────────────────────
    finding_op_idx = {op: i for i, op in enumerate(FINDING_OP_ORDER)}
    remediation_op_idx = {op: i for i, op in enumerate(REMEDIATION_OP_ORDER)}
    verification_op_idx = {op: i for i, op in enumerate(VERIFICATION_OP_ORDER)}
    def dedup(steps: list[dict]) -> list[dict]:
        seen_keys = set()
        out = []
        for s in steps:
            k = (s["system_id"], s["resource_id"], s["operation"])
            if k not in seen_keys:
                seen_keys.add(k)
