        if file_id in self._cache:
            return self._cache[file_id]
        full_path = DATASET / file_path
        if not full_path.exists():
            self._cache[file_id] = None
            return None
        suffix = full_path.suffix.lower()
        try:
            if suffix == ".json":
                with open(full_path, encoding="utf-8") as f:
                    content = json.load(f)
            elif suffix in (".log", ".txt"):
                with open(full_path, encoding="utf-8") as f:
                    content = f.read()
            elif suffix == ".sql":
                with open(full_path, encoding="utf-8") as f:
                    content = f.read()
            else:
                content = None
        except Exception:
            content = None
        self._cache[file_id] = content
        return content

