    def _index_text(self, file_id, captured_at, content, file_path):
        lines = content.split("\n")
        for line in lines:
            relevant_events = [
                "event=profile_lookup_completed",
                "event=index_query_completed",
                "event=analytics_profile_read_completed",
                "event=connector_config_read_completed",
                "event=restore_policy_read_completed",
                "event=support_ticket_read_completed",
                "event=audit_record_read_completed",
            ]
            if not any(ev in line for ev in relevant_events):
                continue
            fields = {}
            for match in re.finditer(r'(\w+)=([^\s]+)', line):
                fields[match.group(1)] = match.group(2)
            emails = []
            refs = []
            for k in ("lookup_key", "customer_email", "requester_email"):
                v = fields.get(k, "null")
                if v and v != "null" and "@" in v:
                    emails.append(v.strip().lower())
            for k in ("customer_reference",):
                v = fields.get(k, "null")
                if v and v != "null" and v.startswith("user_"):
                    refs.append(v.strip())
            resource_id = fields.get("resource_id", "")
            service = fields.get("service", "unknown")
            extra = {}
            if "enabled" in fields:
                extra["enabled"] = fields["enabled"] == "true"
            if "restore_allowed" in fields:
                extra["restore_allowed"] = fields.get("restore_allowed") == "true"
            if "http_status" in fields:
                try:
                    extra["status_code"] = int(fields.get("http_status", 0))
                except Exception:
                    pass
            if "rows" in fields:
                try:
                    extra["rows"] = int(fields.get("rows", 0))
                except Exception:
                    pass
            if "result" in fields:
                extra["result"] = fields.get("result")
            if "retention_until" in fields:
                extra["retention_until"] = fields.get("retention_until")
            if "event_code" in fields:
                extra["event_code"] = fields.get("event_code")
            rec = {
                "file_id": file_id, "captured_at": captured_at,
                "system": service, "resource_id": resource_id,
                "type": "log_record", "raw": fields, **extra,
            }
            self._add_to_index(emails, refs, rec)

    def find_records_for_user(self, user_id, all_emails, all_phones, audit_at):
        self.build_index()
        audit_ts = parse_iso(audit_at)
        seen = set()
        results = []

        def add_if_new(rec):
            key = (rec["file_id"], rec["system"], rec["resource_id"])
            if key not in seen:
                cap_ts = parse_iso(rec.get("captured_at", ""))
                if cap_ts and audit_ts and cap_ts <= audit_ts:
                    seen.add(key)
                    results.append(rec)

        for email in all_emails:
            for rec in self._email_index.get(email, []):
                add_if_new(rec)
        if user_id:
            for rec in self._user_ref_index.get(user_id, []):
                add_if_new(rec)
        return results


def search_sql_evidence(manifest, all_emails, all_phones, user_id, audit_at):
    audit_ts = parse_iso(audit_at)
    results = []
    for entry in manifest:
        file_id = entry["file_id"]
        file_path = entry["file_path"]
        captured_at = entry["captured_at"]
        if not file_path.endswith(".sql"):
            continue
        cap_ts = parse_iso(captured_at)
        if cap_ts and audit_ts and cap_ts > audit_ts:
            continue
        full_path = DATASET / file_path
        if not full_path.exists():
            continue
        try:
            with open(full_path, encoding="utf-8") as f:
                sql_content = f.read()
        except Exception:
            continue
        try:
            conn = sqlite3.connect(":memory:")
            conn.row_factory = sqlite3.Row
            cursor = conn.cursor()
            cursor.executescript(sql_content)
            conn.commit()
            cursor.execute("SELECT name FROM sqlite_master WHERE type='table'")
            tables = [row[0] for row in cursor.fetchall()]
            for table in tables:
                try:
                    cursor.execute(f'PRAGMA table_info("{table}")')
                    columns = [col[1] for col in cursor.fetchall()]
                    conditions = []
                    params = []
                    for col in columns:
                        col_lower = col.lower()
                        if col_lower in ("email", "owner_email", "customer_email", "requester_email"):
                            for em in all_emails:
                                conditions.append(f'lower("{col}") = ?')
                                params.append(em.lower())
                        elif col_lower in ("phone", "customer_phone"):
                            for ph in all_phones:
                                conditions.append(f'"{col}" = ?')
                                params.append(ph)
                        elif col_lower in ("user_id", "customer_reference", "subject_reference"):
                            if user_id:
                                conditions.append(f'"{col}" = ?')
                                params.append(user_id)
                    if not conditions:
                        continue
                    where_clause = " OR ".join(conditions)
                    cursor.execute(f'SELECT * FROM "{table}" WHERE {where_clause}', params)
                    rows = cursor.fetchall()
                    for row in rows:
                        row_dict = dict(row)
                        resource_id = (row_dict.get("resource_id") or row_dict.get("id") or
                                       row_dict.get("record_id") or f"{table}_row")
                        system = infer_system_from_table(table)
                        rec = {
                            "file_id": file_id, "captured_at": captured_at,
                            "system": system, "resource_id": str(resource_id),
                            "type": "sql_record", "table": table, "raw": row_dict,
                        }
                        results.append(rec)
                except sqlite3.Error:
                    continue
            conn.close()
        except sqlite3.Error:
            continue
    return results


def infer_system_from_table(table_name):
    t = table_name.lower()
    if "account" in t:
        return "account_service"
    if "search" in t or "index" in t:
        return "search_service"
    if "support" in t or "ticket" in t:
        return "support_platform"
    if "analytic" in t:
        return "analytics_platform"
    if "marketing" in t:
        return "marketing_platform"
    if "export" in t:
        return "export_service"
    if "backup" in t or "archive" in t:
        return "backup_service"
    if "audit" in t or "security" in t:
        return "security_service"
    if "integration" in t or "connector" in t or "data_flow" in t:
        return "integration_service"
    if "tombstone" in t or "deleted" in t or "identity" in t:
        return "identity_service"
    if "email" in t or "delivery" in t or "notification" in t:
        return "email_delivery_service"
    return "unknown"


def classify_record(rec, deletion_rules):
    system = rec.get("system", "unknown")
    rec_type = rec.get("type", "")
    if rec_type in ("tombstone", "snapshot_record") and rec.get("collection"):
        col = rec.get("collection", "").lower()
        if "tombstone" in col or "deleted_customer" in col:
            system = "identity_service"
    if rec_type == "data_flow":
        data_cat = "SECONDARY_IDENTIFIER"
        action = deletion_rules.get(data_cat, "DELETE")
        return action, data_cat, "integration_service"
    if rec_type == "backup_restore":
        data_cat = "BACKUP_ARCHIVE"
        action = deletion_rules.get(data_cat, "RETAIN")
        return action, data_cat, "backup_service"
    if rec_type == "audit_record":
        data_cat = "SECURITY_AUDIT_LOG"
        action = deletion_rules.get(data_cat, "RETAIN")
        return action, data_cat, "security_service"
    data_cat = SYSTEM_CATEGORY_MAP.get(system, "USER_PROFILE")
    action = deletion_rules.get(data_cat, "DELETE")
    return action, data_cat, system


def is_record_present(rec):
    t = rec.get("type", "")
    if t == "account_profile":
        return rec.get("status_code") == 200 and rec.get("profile") is not None
    if t == "search_index":
        return rec.get("total_hits", 0) > 0
    if t == "analytics_profile":
        profile = rec.get("profile") or rec.get("raw") or {}
        return profile.get("email") is not None or profile.get("customer_reference") is not None
    if t == "data_flow":
        return rec.get("enabled", False)
    if t == "backup_restore":
        return rec.get("restore_allowed", False)
    if t == "audit_record":
        return True
    if t == "tombstone":
        raw = rec.get("raw", {})
        return any(raw.get(f) is not None for f in ["name", "email", "phone", "email_hash"])
    if t == "log_record":
        status = rec.get("status_code", 200)
        rows = rec.get("rows", 1)
        result = rec.get("result", "hit")
        if status == 404 or rows == 0:
            return False
        return result == "hit" or rows > 0
    if t == "sql_record":
        return True
    if t == "snapshot_record":
        raw = rec.get("raw", {})
        col = rec.get("collection", "").lower()
        if "tombstone" in col or "deleted" in col:
            return any(raw.get(f) is not None for f in ["name", "email", "phone", "email_hash"])
        return True
    return True


def has_pii_exposed(rec):
    t = rec.get("type", "")
    raw = rec.get("raw") or {}
    profile = rec.get("profile") or {}
    if t == "analytics_profile":
        return raw.get("email") is not None or profile.get("email") is not None or raw.get("customer_reference") is not None
    if t == "support_ticket":
        return (raw.get("requester_email") is not None or
                raw.get("requester_name") is not None or
                raw.get("requester_phone") is not None)
    if t == "tombstone":
        return any(raw.get(f) is not None for f in ["name", "email", "phone", "email_hash"])
    if t == "log_record":
        fields = rec.get("raw", {})
        v = fields.get("customer_email", "null")
        return v and v not in ("null", "")
    return False


def make_step(step_no, phase, system_id, resource_id, operation, state, evidence_id):
    return {
        "step_no": step_no,
        "phase": phase,
        "system_id": system_id,
        "resource_id": resource_id,
        "operation": operation,
        "state": state,
        "evidence_id": evidence_id,
    }


def build_steps(records, deletion_rules, user_id, is_complete):
    findings = []
    remediations = []
    verifications = []
    handled = set()

    for rec in records:
        action, data_cat, system_id = classify_record(rec, deletion_rules)
        resource_id = rec.get("resource_id", "")
        file_id = rec.get("file_id", "")
        if not resource_id:
            continue
        key = (system_id, resource_id)
        if key in handled:
            continue
        handled.add(key)
        present = is_record_present(rec)
        pii = has_pii_exposed(rec)
        rec_type = rec.get("type", "")

        if rec_type == "data_flow":
            enabled = rec.get("enabled", False)
            if enabled:
                if not is_complete:
                    findings.append(make_step(0, "FINDING", system_id, resource_id, "REPORT_ACTIVE_DATA_FLOW", "ACTIVE", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id, "DISABLE_DATA_FLOW", "DISABLED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_DATA_FLOW_DISABLED", "DISABLED", ""))
            else:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_DATA_FLOW_DISABLED", "DISABLED", file_id))
            continue

        if rec_type == "backup_restore":
            restore_allowed = rec.get("restore_allowed", False)
            if restore_allowed:
                if not is_complete:
                    findings.append(make_step(0, "FINDING", system_id, resource_id, "REPORT_RESTORE_RISK", "ACTIVE", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id, "BLOCK_RESTORE", "BLOCKED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RESTORE_BLOCKED", "BLOCKED", ""))
            else:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RESTORE_BLOCKED", "BLOCKED", file_id))
            continue

        if rec_type == "audit_record" or data_cat == "SECURITY_AUDIT_LOG":
            if is_complete:
                verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_PRESENT", "PRESENT", file_id))
            else:
                verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_PRESENT", "PRESENT", ""))
            continue

        if rec_type == "tombstone" or (data_cat == "ACCOUNT_TOMBSTONE" and system_id == "identity_service"):
            if pii:
                if not is_complete:
                    findings.append(make_step(0, "FINDING", system_id, resource_id, "REPORT_EXPOSED_PII", "PRESENT", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id, "REDACT_RECORD", "REDACTED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_REDACTED", "REDACTED", ""))
            else:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_REDACTED", "REDACTED", file_id))
            continue

        if action == "DELETE":
            if present:
                if not is_complete:
                    findings.append(make_step(0, "FINDING", system_id, resource_id, "REPORT_REMAINING_RECORD", "PRESENT", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id, "DELETE_RECORD", "ABSENT", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_ABSENT", "ABSENT", ""))
            else:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_ABSENT", "ABSENT", file_id))
        elif action == "REDACT":
            if pii or present:
                if not is_complete:
                    op = "REPORT_EXPOSED_PII" if pii else "REPORT_REMAINING_RECORD"
                    findings.append(make_step(0, "FINDING", system_id, resource_id, op, "PRESENT", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id, "REDACT_RECORD", "REDACTED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_REDACTED", "REDACTED", ""))
            else:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_REDACTED", "REDACTED", file_id))
        elif action == "ANONYMIZE":
            if pii or present:
                if not is_complete:
                    op = "REPORT_EXPOSED_PII" if pii else "REPORT_REMAINING_RECORD"
                    findings.append(make_step(0, "FINDING", system_id, resource_id, op, "PRESENT", file_id))
                    remediations.append(make_step(0, "REMEDIATION", system_id, resource_id, "ANONYMIZE_RECORD", "ANONYMIZED", ""))
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_ANONYMIZED", "ANONYMIZED", ""))
            else:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_ANONYMIZED", "ANONYMIZED", file_id))
        elif action == "RETAIN":
            if present:
                if is_complete:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_PRESENT", "PRESENT", file_id))
                else:
                    verifications.append(make_step(0, "VERIFICATION", system_id, resource_id, "VERIFY_RECORD_PRESENT", "PRESENT", ""))

    finding_op_idx = {op: i for i, op in enumerate(FINDING_OP_ORDER)}
    remediation_op_idx = {op: i for i, op in enumerate(REMEDIATION_OP_ORDER)}
    verification_op_idx = {op: i for i, op in enumerate(VERIFICATION_OP_ORDER)}

    def dedup(steps):
        seen_keys = set()
        out = []
        for s in steps:
            k = (s["system_id"], s["resource_id"], s["operation"])
            if k not in seen_keys:
                seen_keys.add(k)
                out.append(s)
        return out

    findings = dedup(findings)
    remediations = dedup(remediations)
    verifications = dedup(verifications)
    findings.sort(key=lambda s: (finding_op_idx.get(s["operation"], 99), s["system_id"], s["resource_id"]))
    remediations.sort(key=lambda s: (remediation_op_idx.get(s["operation"], 99), s["system_id"], s["resource_id"]))
    verifications.sort(key=lambda s: (verification_op_idx.get(s["operation"], 99), s["system_id"], s["resource_id"]))
    all_steps = findings + remediations + verifications
    for i, step in enumerate(all_steps, 1):
        step["step_no"] = i
    return all_steps


def determine_status(records, deletion_rules):
    for rec in records:
        action, data_cat, system_id = classify_record(rec, deletion_rules)
        rec_type = rec.get("type", "")
        if rec_type == "data_flow":
            if rec.get("enabled", False):
                return "INCOMPLETE"
        elif rec_type == "backup_restore":
            if rec.get("restore_allowed", False):
                return "INCOMPLETE"
        elif rec_type == "audit_record" or data_cat == "SECURITY_AUDIT_LOG":
            pass
        elif rec_type == "tombstone":
            if has_pii_exposed(rec):
                return "INCOMPLETE"
        elif action == "DELETE":
            if is_record_present(rec):
                return "INCOMPLETE"
        elif action in ("REDACT", "ANONYMIZE"):
            if has_pii_exposed(rec) or is_record_present(rec):
                return "INCOMPLETE"
    return "COMPLETE"


def process_case(case, identities, audit_log, evidence_store, sql_manifest, deletion_rules):
    case_id = case["case_id"]
    email = case["email"]
    request_text = case.get("request_text", "")
    audit_at = case["audit_at"]

    if not is_deletion_request(request_text):
        return {"case_id": case_id, "deletion_status": "NOT_APPLICABLE", "steps_json": "[]"}

    user_id, all_emails, all_phones = resolve_user(email, identities, audit_log)
    evidence_records = evidence_store.find_records_for_user(user_id, all_emails, all_phones, audit_at)
    sql_records = search_sql_evidence(sql_manifest, all_emails, all_phones, user_id, audit_at)
    evidence_records.extend(sql_records)
    status = determine_status(evidence_records, deletion_rules)
    is_complete = status == "COMPLETE"
    steps = build_steps(evidence_records, deletion_rules, user_id, is_complete)
    steps_json = json.dumps(steps, ensure_ascii=False, separators=(",", ":"))
    return {"case_id": case_id, "deletion_status": status, "steps_json": steps_json}


def main():
    print("Loading dataset files...")
    deletion_rules = {}
    for row in load_csv(DATASET / "deletion_rules.csv"):
        deletion_rules[row["data_category"]] = row["required_action"]
    identities = {}
    for row in load_csv(DATASET / "user_identities.csv"):
        identities[row["user_id"]] = row
    audit_log = load_csv(DATASET / "user_audit_log.csv")
    manifest = load_csv(DATASET / "evidence_files.csv")
    sql_manifest = [e for e in manifest if e["file_path"].endswith(".sql")]
    print(f"Loaded {len(identities)} identities, {len(audit_log)} audit entries, {len(manifest)} evidence files")

    print("Building evidence index...")
    evidence_store = EvidenceStore(manifest)
    evidence_store.build_index()
    print("Index built.")

    requests = load_csv(DATASET / "deletion_requests.csv")
    print(f"Processing {len(requests)} cases...")

    results = []
    for i, case in enumerate(requests, 1):
        if i % 100 == 0:
            print(f"  {i}/{len(requests)}...")
        result = process_case(case, identities, audit_log, evidence_store, sql_manifest, deletion_rules)
        results.append(result)

    results.sort(key=lambda r: r["case_id"])
    print(f"Writing {len(results)} rows to {OUTPUT_CSV}...")
    with open(OUTPUT_CSV, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f, quoting=csv.QUOTE_ALL)
        writer.writerow(["case_id", "deletion_status", "steps_json"])
        for row in results:
            writer.writerow([row["case_id"], row["deletion_status"], row["steps_json"]])
    print(f"Done!")
    statuses = {}
    for r in results:
        s = r["deletion_status"]
        statuses[s] = statuses.get(s, 0) + 1
    print(f"Summary: {statuses}")


if __name__ == "__main__":
    main()
