"""Debug case_15 and case_17 evidence lookup."""
import sys, csv
sys.path.insert(0, 'code')

import importlib.util
spec = importlib.util.spec_from_file_location('main', 'code/main.py')
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)

def load_csv(p):
    with open(p, newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))

identities = {r['user_id']: r for r in load_csv('dataset/user_identities.csv')}
audit_log = load_csv('dataset/user_audit_log.csv')
manifest = load_csv('dataset/evidence_files.csv')
store = m.EvidenceStore(manifest)
store.build_index()

sample_cases = {r['case_id']: r for r in load_csv('dataset/sample_deletion_requests.csv')}

for cid in ['case_15', 'case_17']:
    case = sample_cases[cid]
    uid, emails, phones = m.resolve_user(case['email'], identities, audit_log)
