import re
# Check trace_id first pass
trace_context = {}
for line in content.split('\n'):
    if 'trace_id=' not in line:
        continue
    tf = {m2.group(1): m2.group(2) for m2 in re.finditer(r'(\w+)=([^\s]+)', line)}
    tq = {m2.group(1): m2.group(2) for m2 in re.finditer(r'(\w+)="([^"]+)"', line)}
    tf.update(tq)
    tid = tf.get('trace_id', '')
    t_emails = []
    for k in ('lookup_key', 'subject_key', 'scan_key', 'match_key', 'customer_email', 'requester_email', 'correlation_key', 'matched_value'):
        v = tf.get(k, '')
        if v and '@' in v:
            t_emails.append(v.strip().lower())
    if t_emails:
        trace_context[tid] = t_emails
        print(f"  Trace {tid}: emails={t_emails}")
print(f"  trace_context: {trace_context}")
